actions.action:
result: f.text_0,
subor: f.file_0;

def groupId = findCase{it.processIdentifier.eq("org_group").and(it.author.id.eq(loggedUser().id))}?.stringId
def regions = [:]
def districts = [:]
new File(subor.value.path as String).splitEachLine(",") { cells ->
    try {
        def region_name = cells[0]
        def district_name = cells[1]
        def municipality_name = cells[2]

        def region = regions[region_name]
		if (region == null) {
			region = createCase("${groupId}_region_2" as String, region_name)
			regions[region_name] = region
		}
        def district = districts[district_name]
        if (district == null) {
            district = createCase("${groupId}_district_2" as String, district_name)
			districts[district_name] = district
            def add_district_task = assignTask("1", region)
            setData(add_district_task, [
                "text_0": ["value":district.stringId, "type":"text"],
                "text_1": ["value":district.title, "type":"text"]
            ])
            finishTask(add_district_task)
        }
        def municipality = createCase("${groupId}_municipality_2" as String, municipality_name)
        def add_municipality_task = assignTask("1", district)
        setData(add_municipality_task, [
            "text_0": ["value":municipality.stringId, "type":"text"],
            "text_1": ["value":municipality.title, "type":"text"]
        ])
        finishTask(add_municipality_task)
		change result value { "${result.value}${cells}: imported successfully\n" as String }
    } catch (Exception e) {
        change result value { "${result.value}${cells}:${e.message}\n" as String }
    }
}
